<?php require '_init.php';$pageTitle='Manage products';if(post()){verify_csrf();$id=number('id');switch(textval('action')){case 'toggle':$p=query('SELECT * FROM products WHERE id=?',[$id])->fetch();if($p){if($p['is_sold_out']&&$p['stock']<1)flash('Add stock before marking this product In Stock.');else{query('UPDATE products SET is_sold_out=1-is_sold_out WHERE id=?',[$id]);flash('Availability updated.');}}break;case 'archive':query('UPDATE products SET is_active=0 WHERE id=?',[$id]);flash('Product deleted from the storefront. Order history is preserved.');break;case 'restore':query('UPDATE products SET is_active=1 WHERE id=?',[$id]);flash('Product restored.');break;}redirect('admin/products.php');}$products=query(product_sql().' ORDER BY p.is_active DESC,p.id')->fetchAll();require '../includes/header.php';?><section class="container section"><div class="section-head"><div><span class="eyebrow">YOUR CATALOGUE</span><h1>Products</h1></div><a class="button" href="<?=e(url('admin/product-edit.php'))?>">Add perfume</a></div><div class="table-wrap"><table><thead><tr><th>Perfume</th><th>Price</th><th>Stock</th><th>Availability</th><th>Manage</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><div class="table-product"><img src="<?=e(url($p['image']?:'images/placeholder.svg'))?>" alt=""><div><b><?=e($p['name'])?></b><br><span class="muted"><?=e($p['brand'].' · '.$p['category'])?><?=$p['is_active']?'':' · Archived'?></span></div></div></td><td><?=money($p['price'])?></td><td class="<?=$p['stock']<=5?'out':''?>"><?=$p['stock']?><?=$p['stock']<=5?' · Low':''?></td><td><form method="post"><?php csrf();?><input type="hidden" name="id" value="<?=$p['id']?>"><button class="<?=available($p)?'outline':'danger'?>" name="action" value="toggle"><?=available($p)?'In Stock':'Sold Out'?></button></form></td><td><div class="actions"><a href="<?=e(url('admin/product-edit.php?id='.$p['id']))?>">Edit</a><form method="post" data-confirm="<?=$p['is_active']?'Delete this perfume from the storefront?':'Restore this perfume?'?>"><?php csrf();?><input type="hidden" name="id" value="<?=$p['id']?>"><button class="link" name="action" value="<?=$p['is_active']?'archive':'restore'?>"><?=$p['is_active']?'Delete':'Restore'?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><?php require '../includes/footer.php';?>
